    "fmd-name": "Foot and Mouth Disease (FMD)",
    "fmd-vernacular": "Vernacular: खुरपका-मुंहपका रोग",
    "fmd-prev": "Bi-annual vaccination (pre-monsoon and post-monsoon) under the National Animal Disease Control Programme (NADCP). Quarantine new herd entries for 21 days. Disinfect shed gates with 4% sodium carbonate.",
    "fmd-firstaid": "Wash oral lesions with 1% potassium permanganate or alum solution. Apply boro-glycerine to mouth ulcers and apply neem/antiseptic ointment to hoof wounds to repel maggots. Provide soft gruel feed.",
    "fmd-vet": "Contact vet immediately upon noticing blisters. Secondary infections in hooves can permanently disable draught animals; pregnant cattle may abort.",
    "hs-name": "Hemorrhagic Septicemia (HS / Galghontu)",
    "hs-vernacular": "Vernacular: गलघोंटू / घुर्रका",
    "hs-prev": "Mandatory annual pre-monsoon vaccination (May-June). Isolate sick animals immediately. Avoid grazing in waterlogged marshy lowlands during rains.",
    "hs-firstaid": "Keep the animal in a calm, shaded, well-ventilated spot. Do NOT force-drench oral liquids as throat paralysis causes fatal aspiration pneumonia.",
    "hs-vet": "EMERGENCY: HS has up to 80% mortality within 24 hours. Intravenous antibiotics (Sulfadimidine, Oxytetracycline) must be administered by a veterinarian in the early pyrexic stage.",
    "bq-name": "Black Quarter (BQ / Langda Bukhar)",
    "bq-vernacular": "Vernacular: जहरबाद / लंगड़िया",
    "bq-prev": "Annual vaccination of young stock (6 months to 2 years) before monsoon. Deep carcass burial with quicklime to prevent Clostridial soil spore contamination.",
    "bq-firstaid": "Confine animal to soft bedding. Hot fomentation on swollen thigh muscles is contraindicated as heat accelerates bacterial toxin release.",
    "bq-vet": "CRITICAL EMERGENCY: High doses of crystalline penicillin and anti-inflammatory therapy must be initiated by a vet before muscular gangrene sets in.",
    "mast-name": "Bovine Mastitis (Udder Inflammation)",
    "mast-vernacular": "Vernacular: थनैला रोग / स्तन सूजन",
    "mast-prev": "Clean milking hygiene: full-hand milking (no knuckling), dry teat wiping, post-milking teat dips with 0.5% povidone-iodine, and dry cow therapy during rest period.",
    "mast-firstaid": "Frequent stripping of affected quarter (every 2-3 hours) into a disinfectant container (never on floor). Apply cold water packs to hot, swollen quarters.",
    "mast-vet": "URGENT: Call vet within hours of abnormal milk or teat hardness. Vet will perform California Mastitis Test (CMT) and administer intramammary antibiotic infusion.",
    "ppr-name": "Peste des Petits Ruminants (PPR / Goat Plague)",
    "ppr-vernacular": "Vernacular: बकरी प्लेग / महामारी",
    "ppr-prev": "Single dose of live attenuated PPR vaccine gives lifetime immunity (effective for 3 years). Vaccinate all kids at 3 months of age. Restrict movement of infected herds.",
    "ppr-firstaid": "Clean crusty eye and nasal discharges with warm sterile saline. Offer oral rehydration solution (ORS with electrolytes) to combat dehydration from diarrhea.",
    "ppr-vet": "Contact vet immediately. Although viral, secondary bacterial pneumonia and gastroenteritis require broad-spectrum antibiotics and supportive fluid therapy.",
    "bloat-name": "Bloat / Ruminal Tympany",
    "bloat-vernacular": "Vernacular: अफरा / पेट का फूलना",
    "bloat-prev": "Never feed wet, dewy leguminous greens (alfalfa, young clover) on an empty stomach. Feed dry roughage (straw/hay) before lush pasture turnout.",
    "bloat-firstaid": "Keep animal standing with front legs elevated. Drench with 200-300 ml mustard or groundnut oil mixed with 20 ml oil of turpentine to break froth.",
    "bloat-vet": "EMERGENCY: If animal is staggering, grunting, or gasping with cyanotic blue tongue, vet must pass a stomach tube or use a trocar & cannula to relieve gas immediately.",
    "bruc-name": "Bovine Brucellosis (Contagious Abortion)",
    "bruc-vernacular": "Vernacular: छूतदार गर्भपात (बैंग्स रोग)",
    "bruc-prev": "Single vaccination of female calves at 4-8 months with Brucella abortus Cotton Strain 19. Never vaccinate adult cows or male calves. Test herd periodically.",
    "bruc-firstaid": "ZOONOTIC ALERT: Wear heavy gloves when handling aborted fetus or placenta. Burn or deeply bury aborted material with bleaching powder. Disinfect area.",
    "bruc-vet": "Report to veterinary officer immediately. Serum agglutination testing must be done to screen the whole herd. Infected milk must be thoroughly boiled.",
    "pox-name": "Sheep Pox & Goat Pox",
    "pox-vernacular": "Vernacular: चेचक / माता रोग",
    "pox-prev": "Annual vaccination with live attenuated Sheep Pox / Goat Pox vaccine (0.5 ml subcutaneous). Quarantine affected pens and burn infected beddings.",
    "pox-firstaid": "Isolate affected animals. Wash skin lesions with 1:1000 potassium permanganate solution. Apply boric acid ointment to crusts to relieve irritation.",
    "pox-vet": "Contact vet. High mortality occurs in young lambs/kids due to systemic internal nodules and secondary lung damage requiring antibiotic coverage.",
    "mf-name": "Milk Fever / Hypocalcemia",
    "mf-vernacular": "Vernacular: दुग्ध ज्वर (शरीर ठंडा पड़ना)",
    "mf-prev": "Feed low calcium diet during late dry period to stimulate parathyroid activity. Drench oral calcium paste immediately after calving and 24 hours later.",
    "mf-firstaid": "Prop animal upright in sternal recumbency using straw bales to avoid bloat. Keep warm with blankets. Never drench liquids while neck is kinked.",
    "mf-vet": "URGENT EMERGENCY: Veterinarian must administer slow intravenous Calcium Borogluconate (400-500 ml) under cardiac monitoring. Recovery is typically dramatic.",
