    "et-vernacular": "Vernacular: फड़किया / अचानक मृत्यु",
    "et-prev": "Annual pre-monsoon vaccination of sheep and goats. Avoid abrupt switches to rich concentrate grains or lush green clover pastures.",
    "et-firstaid": "Immediately remove flock from rich grazing pasture or grain concentrates. Offer dry fibrous hay and clean drinking water.",
    "et-vet": "EMERGENCY: Due to rapid bacterial toxin release, animals often succumb in 2-4 hours. Contact vet for antitoxin administration and herd-wide prophylaxis.",
