    "pillar-min-desc": "Calcium, phosphorus, trace minerals (zinc, iodine, cobalt, selenium) and common salt prevent repeat breeding, milk fever, and sustain peak lactation.",
    "pillar-water-title": "5. Ad-Libitum Clean Drinking Water",
    "pillar-water-desc": "Milk is 87% water! An adult dairy animal drinks 60-100 liters daily. Always provide cool, clean, non-saline drinking water accessible 24/7.",
    "species-nut-tag": "Species Breakdown",
    "species-nut-title": "Customized Feeding by Livestock Type",
    "species-nut-sub": "Explore specialized nutritional strategies designed for cows, buffalos, goats, and sheep.",
    "tab-all-nut": "All Species (4)",
    "tab-cow-nut": "Cow (गाय)",
    "tab-buffalo-nut": "Buffalo (भैंस)",
    "tab-goat-nut": "Goat (बकरी)",
    "tab-sheep-nut": "Sheep (भेड़)",
    "cow-nut-title": "🐄 Dairy Cattle Feeding Management",
    "cow-nut-p1": "Dairy cows require a 2:1 ratio of roughage to concentrates. For high yielders producing >15L daily, include bypass fat (100g) and bypass protein to curb negative energy balance in early lactation.",
    "buf-nut-title": "🐃 Water Buffalo High-Fat Nutrition",
    "buf-nut-p1": "Water buffaloes efficiently digest fibrous dry roughage. Since buffalo milk contains 7-8% butterfat, provide 1 kg concentrate for every 2 kg of milk produced (compared to 2.5 kg in cattle).",
    "goat-nut-title": "🐐 Goat Browsing & Grazing Management",
    "goat-nut-p1": "Goats are selective browsers. Incorporate tree loppings (Neem, Subabul, Ber, Peepal) which are naturally rich in tannins that suppress internal gastrointestinal worm burdens.",
    "sheep-nut-title": "🐑 Sheep Feeding & Grazing Management",
    "sheep-nut-p1": "Sheep are close-grazers that thrive on natural grasslands and stubble. Flushing (offering 200g grain supplement for 2 weeks prior to breeding) increases ovulation rates and twinning percentage. Caution: Ensure mineral supplements are formulated specifically for sheep with low copper levels to prevent lethal chronic copper poisoning.",
    "tox-box-title": "⚠️ Critical Livestock Feed Safety & Toxicity Warnings",
    "tox-urea-title": "Urea Toxicity:",
    "tox-urea-desc": "Never feed raw urea to calves under 6 months. Never exceed 1% urea in total dry matter. Symptoms include muscle tremors, bloat, and frothing at mouth.",
    "tox-hcn-title": "Hydrocyanic Acid (HCN) in Sorghum:",
    "tox-hcn-desc": "Immature or drought-stressed young sorghum (under 45-50 days) contains lethal Dhurrin / HCN. Always irrigate and wait until flowering stage before harvesting.",
    "tox-afla-title": "Aflatoxin / Moldy Straw:",
    "tox-afla-desc": "Fungus-spoiled oil cakes or damp straw contain hepatotoxic aflatoxins that impair immunity and pass into milk.",
    "tox-bloat-title": "Excess Legumes / Frothy Bloat:",
    "tox-bloat-desc": "Grazing dewy berseem/alfalfa without prior dry roughage triggers lethal frothy bloat. Always feed dry straw first.",
    "care-banner-title": "Preventive Animal Care",
    "care-banner-subtitle": "“Simple habits today can support healthier livestock tomorrow.” Master biosecurity, routine vaccination, housing hygiene, and track shot due dates.",
    "care-disc-title": "Preventive Healthcare Notice",
    "care-disc-text": "Vaccination schedules and deworming protocols may differ according to state veterinary recommendations, regional endemic disease prevalence, and local climate patterns. Always consult your district veterinary officer before administering vaccines.",
    "rem-tool-badge": "Future-Ready Tool",
    "rem-tool-title": "📅 Livestock Vaccination Reminder Tool",
    "rem-tool-sub": "Add upcoming vaccine schedules for your herd. Data is securely saved in your browser (LocalStorage) so you never miss a critical booster dose!",
