    "pillars-tag": "Proactive Husbandry",
    "pillars-title": "6 Core Pillars of Preventive Care",
    "pillars-subtitle": "“Simple habits today can support healthier livestock tomorrow.”",
    "cp-shelter-title": "1. Clean, Dry & Well-Ventilated Sheds",
    "cp-shelter-desc": "Ammonia fumes and wet floors predispose cattle to mastitis, hoof rot, and pneumonia. Use lime powder dusting weekly.",
    "cp-water-title": "2. Clean Troughs & Fresh Water",
    "cp-water-desc": "Algal blooms and stagnant water harbor liver fluke metacercariae and coliforms. Clean troughs with bleaching powder monthly.",
    "cp-deworm-title": "3. Timely Routine Deworming",
    "cp-deworm-desc": "Deworm adult stock 3 times a year (pre-monsoon, post-monsoon, winter). Rotate drug classes (Albendazole, Fenbendazole, Ivermectin).",
    "cp-bio-title": "4. Strict Herd Biosecurity",
    "cp-bio-desc": "Quarantine newly purchased livestock for at least 21 days before mixing with existing herd to stop silent disease transmission.",
    "cp-udder-title": "5. Strict Udder Hygiene",
    "cp-udder-desc": "Wash udders with warm potassium permanganate solution prior to milking. Dip teats in 0.5% povidone-iodine post-milking.",
    "cp-stress-title": "6. Heat & Cold Stress Protection",
    "cp-stress-desc": "Provide summer thatch roofs, ceiling fans, or water misting. In peak winter, protect young calves from chilly drafts using burlap curtains.",
    "check-tag": "Daily & Seasonal Tasks",
    "check-title": "Livestock Management Checklist",
    "check-subtitle": "Interactive tracker to maintain high husbandry standards across your farm.",
    "chk-item-1": "Inspect morning rumination (chewing cud) in all adult cattle and buffaloes.",
    "chk-item-2": "Scrub water troughs and refill with fresh, uncontaminated water.",
    "chk-item-3": "Wash milker hands and cow udders with warm potassium permanganate prior to milking.",
    "chk-item-4": "Inspect sheep and goat hooves for foul odor, softening, or limping (Foot Rot check).",
    "chk-item-5": "Check animal skin folds, ears, and tail bases for ticks and external parasites.",
    "chk-item-6": "Verify vaccination dates in your browser reminder tool for upcoming monsoon booster shots.",
    "vax-table-tag": "Timely Immunization",
