    "contact-banner-title": "About Smart Animal Care",
    "contact-banner-subtitle": "Bridging agricultural technology and veterinary awareness to deliver reliable livestock guidance directly to rural farmers.",
    "contact-disc-title": "Academic College Project Notification",
    "contact-disc-text": "Smart Animal Care is an educational undergraduate capstone project. It is created to demonstrate responsive web architecture, structured animal healthcare dissemination, and future-ready agricultural data management. It does not replace registered veterinary professionals.",
    "about-badge": "Project Overview",
    "about-title": "About the Project",
    "about-desc": "Smart Animal Care is a student project designed to provide farmers and livestock owners with accessible animal healthcare information, nutrition guidance, preventive care information and veterinary assistance resources.",
    "about-aim-title": "🎯 Project Aim & Objectives",
    "aim-1-title": "Democratize Veterinary Awareness:",
    "aim-1-desc": "Translate clinical animal health knowledge into accessible, farmer-friendly terms.",
    "aim-2-title": "Promote Preventive Biosecurity:",
    "aim-2-desc": "Shift livestock management from costly emergency treatments to proactive disease prevention.",
    "aim-3-title": "Scientific Rationing:",
    "aim-3-desc": "Provide practical feed calculators to optimize green fodder, dry straw, and mineral intake for maximum milk yield.",
    "aim-4-title": "Facilitate Medical Access:",
    "aim-4-desc": "Connect rural dairy farmers with qualified veterinary doctors and emergency facilities.",
    "about-scope-title": "🚀 Future Scope & Architectural Vision",
    "about-scope-desc": "The frontend has been built with clean, modular semantics ready for future enterprise expansion:",
    "scope-1-desc": "Python Flask / FastAPI Backend: Dynamic REST endpoints for animal records and doctor appointment bookings.",
    "scope-2-desc": "MySQL Relational Schema: Persistent entities for Animals, Diseases, Rations, Reminders, and Verified Clinics.",
    "scope-3-desc": "Google Maps JavaScript API: Real-time GPS distance calculation and driving directions to the nearest clinic.",
    "scope-4-desc": "AI Disease Symptom Screener: Computer vision image analysis for dermatological conditions like Lumpy Skin Disease.",
    "scope-5-desc": "Offline PWA Support: Service workers enabling farmers to check feeding tables even in zero-network rural zones.",
    "academic-context-note": "Academic Context: Final Year B.Tech / B.Sc Computer Science & Agricultural Informatics Project (2025–2026).",
    "form-badge": "Get in Touch",
    "form-title": "Project Feedback & Inquiry",
