    "faq-tag": "Frequently Asked Questions",
    "faq-title": "Farmer & User Help Center",
    "faq-subtitle": "Quick answers regarding platform usage, medical disclaimers, and veterinary assistance.",
    "faq-q1": "Is Smart Animal Care completely free to use?",
    "faq-a1": "Yes, Smart Animal Care is an open, free educational platform developed for college academic presentation and farmer empowerment. All guides, calculators, reminder utilities, and clinic listings are 100% accessible without any fee or subscription.",
    "faq-q2": "Can I use this website to treat my sick cow on my own?",
    "faq-a2": "No. This platform is designed solely to build awareness, assist in early detection of symptoms, and encourage preventive biosecurity. Diagnosis, prescription of antibiotics, surgeries, and clinical interventions require a physical examination by a registered veterinary doctor. Self-administering prescription drugs can result in fatal toxicity or drug resistance.",
    "faq-q3": "How does the Vaccination Reminder tool work?",
    "faq-a3": "The reminder tool leverages your web browser's modern localStorage API. When you add a schedule (animal tag, vaccine name, and due date), the browser saves it locally on your computer or mobile phone. Even when you refresh or close the page, your reminders stay saved!",
    "faq-q4": "What should I do immediately during an acute livestock emergency?",
    "faq-a4": "In cases of acute bloat, severe calving difficulty (dystocia), continuous hemorrhage, sudden recumbency, or high fever with throat swelling, immediately dial the National Animal Ambulance helpline at 1962 or contact your nearest veterinary polyclinic directly from our Find a Vet directory.",
    "faq-q5": "How can a veterinarian or clinic add their details to this directory?",
    "faq-a5": "Practitioners can submit their clinic name, registration council number, qualification, address, and consultation hours using the feedback form above. In future updates with a MySQL/Flask backend, an automated registration portal with credential verification will be provided.",
    "modal-success-title": "Inquiry Successfully Recorded!",
    "modal-success-desc": "Thank you for reaching out to the Smart Animal Care project team. All input fields were validated cleanly on the client side.",
    "modal-success-note": "Demonstration Note: In production, this trigger executes an asynchronous fetch('/api/contact', ...) call to a Python Flask API to store submissions in a database and notify administrators via email.",
    "modal-success-btn": "Continue Exploring Platform",
