    "anim-cow-sci": "Bos taurus / Bos indicus",
    "anim-buf-sci": "Bubalus bubalis",
    "anim-goat-sci": "Capra hircus",
    "anim-sheep-sci": "Ovis aries",
    "anim-buf-desc-p": "Renowned for producing dense milk rich in butterfat (7-8%), water buffaloes such as the Murrah, Nili-Ravi, and Mehsana are robust converters of coarse crop residues. They have fewer sweat glands and dark skin, demanding dedicated heat mitigation.",
    "anim-buf-prod-val": "High Fat Milk & Draught",
    "anim-buf-focus-1": "Provide clean wallowing ponds or water splashing twice daily in hot summers.",
    "anim-buf-focus-2": "Inspect wider teat orifices for mud contamination before and after milking.",
    "anim-buf-focus-3": "Watch for silent heat signs during morning and evening milking sessions.",
    "anim-goat-desc-p": "Affectionately known as the farmer’s companion or \"poor man’s cow\", goats are prolific, drought-hardy browsers. Famous Indian breeds including Jamunapari, Black Bengal, and Sirohi supply nutritious milk and meat with minimal starting capital.",
    "anim-goat-temp-val": "39.0°C (102.2°F)",
    "anim-goat-prod-val": "Meat, Milk & Kids",
    "anim-goat-focus-1": "Keep shed floor dry and elevated on slats; goats cannot tolerate damp, muddy floors.",
    "anim-goat-focus-2": "Regularly trim overgrown hooves to forestall contagious foot rot.",
    "anim-goat-focus-3": "Strict adherence to PPR and Enterotoxemia (ET) vaccination calendars.",
    "anim-sheep-desc-p": "Sheep graze close to the ground and excel at utilizing stubble, arid grasses, and hill pastures. Breeds such as the Marwari, Deccani, and Nellore furnish wool, mutton, and rich penning manure, but require protection from wet fleece hypothermia.",
    "anim-sheep-prod-val": "Mutton, Coarse Wool & Manure",
    "anim-sheep-focus-1": "Annual shearing prior to hot months and winter to avoid heat distress and fleece soiling.",
    "anim-sheep-focus-2": "Flock dipping in antiparasitic solution 2-3 weeks post-shearing for tick and mite control.",
    "anim-sheep-focus-3": "Avoid copper-rich cattle supplements to protect sheep from fatal copper toxicity.",
