    "dis-lbl-when-contact": "🚨 When to Contact a Veterinarian:",
    "dis-fmd-warn-p": "Report outbreak immediately to the local government dispensary. Calves under 6 months can die suddenly from myocardial failure (tiger heart) without showing blisters.",
    "dis-btn-find-vet-near": "Find a Veterinarian Near You →",
    "dis-btn-contact-vet-urgently": "Contact Veterinarian Urgently →",
    "dis-btn-emergency-assist": "Find Emergency Vet Assistance →",
    "dis-btn-report-dispensary": "Report to Nearest Dispensary →",
    "dis-hs-warn-p": "EMERGENCY! Death can occur within 12 to 36 hours. A veterinarian must immediately administer IV broad-spectrum antibiotics (sulfa drugs / oxytetracycline) in the earliest febrile stage.",
    "dis-mast-warn-p": "Immediately at the first sign of clots or udder hardness. Delay causes permanent quarter fibrosis or gangrenous mastitis. Antibiotic susceptibility testing is recommended before intramammary infusions.",
    "dis-lsd-warn-p": "Seek veterinary care for anti-inflammatory injections to control pain and secondary bacterial pneumonia. Respiratory distress and throat nodules require emergency care.",
    "dis-bq-warn-p": "Emergency intervention is needed within hours. Penicillin group antibiotics must be injected parenterally and infiltrated around the muscle lesion by a vet before toxemia sets in.",
    "dis-ppr-warn-p": "Mortality can reach 80% in unprotected goat flocks. Immediate veterinary administration of fluids, broad-spectrum antibiotics for secondary pneumonia, and anti-inflammatories is crucial.",
    "dis-bloat-warn-p": "CRITICAL EMERGENCY: Severe bloat compresses the lungs and diaphragm, causing asphyxiation within 1-2 hours. A vet must relieve pressure via stomach tube or trocar-cannula in the left paralumbar fossa.",
    "dis-anthrax-warn-p": "Notify government veterinary authorities immediately. It is dangerous to human handlers (zoonotic). Surviving herd contacts require urgent post-exposure prophylaxis.",
    "dis-bab-warn-p": "Rapid red blood cell destruction causes fatal anemia. A veterinarian must immediately administer specific antiprotozoal drugs (Diminazene aceturate or Imidocarb dipropionate) along with hematinics.",
    "dis-et-warn-p": "Toxins produced by Clostridium perfringens act rapidly. In early stages, a veterinarian can inject hyperimmune antiserum, pain relievers, and protective antitoxins.",
    "dis-reset-filters-btn": "Reset All Filters",
