    "care-p1-title": "1. Clean & Ventilated Shelters",
    "care-p1-desc": "Stagnant moisture and ammonia vapors cause respiratory lesions and mastitis. Ensure shed roofs are at least 10-12 feet high with ridge vents. Build floor with a 1:40 slope towards external drainage channels to keep standings dry.",
    "care-p2-title": "2. Strict Farm Hygiene & Sanitation",
    "care-p2-desc": "Remove cow dung twice daily. Dust shed floors with slaked lime (चूना) weekly to neutralize pathogens. Install a 10% lime or potassium permanganate footbath at the farm entrance to disinfect visitor boots and vehicle tires.",
    "care-p3-title": "3. Timely Vaccination Schedules",
    "care-p3-desc": "Vaccines build specific antibodies against deadly epidemics. Never vaccinate an animal that is running a high fever, severely emaciated, or heavily infested with internal worms, as immune response will fail.",
    "care-p4-title": "4. Seasonal Deworming & Health Exams",
    "care-p4-desc": "Deworm all livestock at least 3-4 times annually (specifically pre-monsoon in May and post-monsoon in October). Rotate dewormer molecules (Albendazole, Fenbendazole, Ivermectin) to prevent parasite drug resistance.",
    "care-p5-title": "5. Continuous Clean Drinking Water",
    "care-p5-desc": "Ensure continuous access to potable water in shaded troughs. Stagnant green-scummed water harbors cyanobacteria, leptospirosis, and liver fluke snails. Scrub water troughs with bleaching powder every 10 days.",
    "care-p6-title": "6. Early Attention & Quarantine Isolation",
    "care-p6-desc": "Observe livestock behavior daily during morning milking. A drop in milk yield, dull ears, dry muzzle, or lack of rumination are early warnings. Immediately isolate any sick or newly purchased animal in a separate quarantine pen.",
    "care-chk-title": "📋 Daily & Weekly Farm Biosecurity Checklist",
    "care-chk-sub": "Click each item as you complete daily farm tasks to track your preventive score!",
    "care-chk-1-title": "Check Water Troughs:",
    "care-chk-1-desc": "Cleaned, filled with cool potable water, free of bird droppings and algal debris.",
    "care-chk-2-title": "Monitor Rumination (Cud Chewing):",
    "care-chk-2-desc": "Verified that resting animals are rhythmically chewing their cud.",
    "care-chk-3-title": "Clean Dung & Dry Bedding:",
    "care-chk-3-desc": "Gutters scraped clean; dry bedding spread under high-yielding cows.",
    "care-chk-4-title": "Post-Milking Teat Disinfection:",
    "care-chk-4-desc": "Teats dipped in 0.5% iodine solution; animals kept standing for 45 minutes.",
    "care-chk-5-title": "Tick & Fly Inspection:",
    "care-chk-5-desc": "Inspected skin folds, tail base, and ears for ticks or fly irritation.",
    "care-chk-6-title": "Feed Quality Inspection:",
    "care-chk-6-desc": "Checked silage and grain bins for mold, moisture, or insect webs.",
