    "hs-name-title": "Hemorrhagic Septicemia (HS)",
    "hs-vernacular-text": "Vernacular: गलघोंटू रोग (Pasteurellosis)",
    "mast-name-title": "Bovine Mastitis",
    "mast-vernacular-text": "Vernacular: थनैला रोग (Udder Inflammation)",
    "lsd-name-title": "Lumpy Skin Disease (LSD)",
    "lsd-vernacular-text": "Vernacular: लंपी त्वचा रोग",
    "bq-name-title": "Black Quarter (BQ)",
    "bq-vernacular-text": "Vernacular: लंगड़ा बुखार / जहरबाद",
    "ppr-name-title": "Peste des Petits Ruminants (PPR)",
    "ppr-vernacular-text": "Vernacular: बकरी प्लेग (Goat Plague)",
    "bloat-name-title": "Acute Bloat / Ruminal Tympany",
    "bloat-vernacular-text": "Vernacular: अफारा (Rumen Gas Distension)",
    "anthrax-name-title": "Anthrax (Bacillus anthracis)",
    "anthrax-vernacular-text": "Vernacular: चिरचिटा / गिल्टी रोग",
    "bab-name-title": "Babesiosis (Redwater Fever)",
    "bab-vernacular-text": "Vernacular: चिचड़ी बुखार / लाल पेशाब",
    "et-name-title": "Enterotoxemia (Pulpy Kidney)",
    "et-vernacular-text": "Vernacular: फिड़किया रोग (Overeating Disease)",
    "hs-prev-text": "Annual vaccination with HS alum-precipitated vaccine strictly prior to monsoon onset (May-June). Avoid working draught animals in heavy rain or swampy pastures during outbreaks.",
    "hs-firstaid-text": "Isolate the sick animal in a cool, dry area. Keep the head elevated to ease airway obstruction. Do not force-drench liquids as fluid can enter the lungs due to pharyngeal swelling.",
    "mast-prev-text": "Dry cow therapy. Practice teat dipping with iodine post-milking. Keep milking platform spotless. Ensure cows stand for at least 30-45 minutes after milking by offering fresh feed while teat canals seal.",
    "mast-firstaid-text": "Perform frequent strip milking of the infected quarter (every 2 hours) and discard infected milk safely. Apply cold compresses or ice packs to reduce acute swelling.",
    "lsd-prev-text": "Heterologous vaccination using Goat Pox vaccine (or Lumpi-ProVacInd). Stringent fly, mosquito, and tick control using neem oil sprays, fly traps, and biosecurity isolation.",
    "lsd-firstaid-text": "Clean burst nodules with betadine solution and apply herbal fly-repellent ointments. Provide tender green grass, electrolyte water, and immunity boosters (turmeric, amla, vitamin E & selenium).",
    "bq-prev-text": "Annual vaccination of young calves (above 6 months) in May before monsoon rains. Avoid grazing over excavated pasture soils where Clostridium chauvoei spores persist for decades.",
    "bq-firstaid-text": "Strictly isolate the animal. Keep bedding soft. Never incise the swelling yourself as escaping spores can contaminate the soil permanently for other livestock.",
    "ppr-prev-text": "PPR live-attenuated vaccine administered at 3-4 months of age provides lasting immunity for 3 years. Quarantine newly bought goats from livestock markets for 15 days before introducing to flock.",
    "ppr-firstaid-text": "Clean crusty eyes and nostrils with warm saline. Clean oral erosions with 0.1% potassium permanganate solution. Provide warm oral rehydration solution (ORS) with electrolytes to combat dehydration.",
    "bloat-prev-text": "Never turn hungry animals out onto lush dewy legume pasture (alfalfa/berseem). Feed dry straw prior to green forage. Avoid sudden changes in grain rations or access to moldy carbohydrate garbage.",
    "bloat-firstaid-text": "Tie a wooden bit in the mouth to encourage chewing and salivation. Walk the animal slowly uphill. Administer 200-300 ml of vegetable cooking oil (mustard or groundnut oil) or antifoaming bloat drench.",
    "anthrax-prev-text": "Annual spore vaccination in known endemic zones. Strictly NEVER open or skin a carcass suspected of Anthrax; exposure to air triggers spore formation which contaminates land for 50+ years.",
    "anthrax-firstaid-text": "Do not touch body fluids! Deeply bury dead animals (at least 6-8 feet deep) sealed with quicklime, or arrange sanitary carcass incineration.",
    "bab-prev-text": "Regular acaricide spraying (Deltamethrin, Amitraz) on animals and shed walls/cracks. Eliminate tick vectors, shear overgrown hair, and avoid introducing tick-laden cattle into clean herds.",
    "bab-firstaid-text": "Keep the sick animal in shade. Offer fresh clean water with molasses/jaggery for glucose support and fresh soft green grass. Remove ticks manually using gloves and tweezers.",
    "et-prev-text": "Vaccinate pregnant ewes/does 2-4 weeks before lambing and kids/lambs at 2 months of age. Avoid sudden changes to heavy cereal grains or rich pasture flush without adaptation.",
    "et-firstaid-text": "Immediately withhold rich concentrates and lush forage. Provide high-fiber coarse hay. Feed oral antacids or baking soda solution to reduce ruminal acidity.",
