    "nut-p2-wheat-desc": "Excellent dry roughage base.",
    "nut-p2-paddy-desc": "Soak or treat with urea-molasses to boost protein availability.",
    "nut-p2-chaff-desc": "Always chaff straw into 1-2 inch lengths to prevent waste and save animal chewing energy.",
    "nut-p3-grain-desc": "Maize, barley, broken wheat.",
    "nut-p3-cake-desc": "Mustard, cottonseed, groundnut, or soybean meal.",
    "nut-p3-bran-desc": "Wheat bran, rice polish, or de-oiled cakes.",
    "nut-p4-min1": "Daily mineral mixture: 50-60g for cattle/buffalo; 10-15g for goat/sheep.",
    "nut-p4-min2": "Hang mineralized salt licks in sheds for free-choice trace mineral intake.",
    "nut-p4-min3": "Proper 2:1 Calcium to Phosphorus ratio prevents Milk Fever post-calving.",
    "nut-p5-wat1": "Dairy cows need 3-4 liters of water for every liter of milk produced.",
    "nut-p5-wat2": "Water must be free from coliforms, heavy nitrates, and algal toxins.",
