    "nut-golden-r1": "Never change diets abruptly; transition gradually over 7 to 10 days.",
    "nut-golden-r2": "Feed concentrates in two equal halves (morning and evening milking).",
    "nut-golden-r3": "Clean the feeding manger daily; remove stale, saliva-soaked, or moldy feed.",
    "nut-species-schedules": "Species Schedules",
    "nut-animal-feeding-guidelines": "Animal-Specific Feeding Guidelines",
    "nut-cow-mgmt-title": "🐄 Dairy Cow Feeding Management",
    "nut-cow-focus-badge": "High Milk Yield Focus",
    "nut-cow-mgmt-desc": "A high-yielding cow requires steady energy to avoid negative energy balance in early lactation (which triggers ketosis). Feed 1 kg concentrate for every 2.5-3.0 liters of milk, plus a 1.0-1.5 kg maintenance allowance. Mix leguminous and non-leguminous green fodder in a 1:3 ratio for balanced rumen crude protein and energy.",
    "nut-th-prod-level": "Production Level",
    "nut-th-green-fodder": "Green Fodder (kg)",
    "nut-th-dry-straw": "Dry Straw (kg)",
    "nut-th-concentrate": "Concentrate (kg)",
    "nut-th-mineral-mix": "Mineral Mix",
    "nut-cow-row-dry": "Dry / Non-Milking (400 kg)",
    "nut-val-30-40g": "30 - 40 grams",
    "nut-cow-row-med": "Medium Milking (8 - 12 L/day)",
    "nut-val-50g": "50 grams",
    "nut-cow-row-high": "High Milking (15+ L/day)",
    "nut-val-60-80g": "60 - 80 grams",
    "nut-buf-mgmt-title": "🐃 Water Buffalo Feeding Management",
    "nut-buf-focus-badge": "High Fat Secretion Focus",
    "nut-buf-mgmt-desc": "Buffaloes excel at digesting lignified, fibrous crop residues. However, because buffalo milk contains 7-8% butterfat, energy requirements per liter of milk are substantially higher than cattle. Feed 1 kg concentrate for every 2.0 liters of buffalo milk. During summer, provide cool drinking water and night-time stall feeding when ambient temperatures drop.",
    "nut-buf-row-dry": "Dry / Maintenance (500 kg)",
    "nut-val-40g": "40 grams",
    "nut-buf-row-lac": "Lactating (8 - 12 L/day)",
    "nut-val-60g": "60 grams",
    "nut-buf-row-gest": "Advanced Gestation (7+ months)",
    "nut-goat-mgmt-title": "🐐 Goat Feeding & Browsing Management",
    "nut-goat-focus-badge": "Selective Browser",
    "nut-goat-mgmt-desc": "Goats possess a mobile split upper lip and prefer browsing tree foliage (Subabul, Neem, Ber, Gliricidia, Sesbania) over pasture grasses. They have a higher dry matter requirement (3.5% to 4.0% of body weight) due to rapid digestive transit. Provide clean water in buckets elevated off the ground to prevent defecation inside water.",
