    "cow-anim-desc": "गाय ग्रामीण अर्थव्यवस्था की रीढ़ है। चाहे गिर, साहीवाल और कांकरेज जैसी देशी नस्लें हों या अधिक दूध देने वाली संकर नस्लें, गायों को निरंतर दूध उत्पादन के लिए नियमित आहार, साफ बिछावन और अयन (थनों) की स्वच्छता आवश्यक है।",
    "cow-fact-gest": "280 - 285 दिन",
    "cow-fact-water": "60 - 90 लीटर",
    "cow-fact-temp": "38.5°C (101.5°F)",
    "cow-fact-prod": "दूध एवं जैविक खाद",
    "cow-focus-1": "खुर फिसलने और लंगड़ेपन से बचाव के लिए खांचेदार कंक्रीट या रबर मैट वाला फर्श रखें।",
    "cow-focus-2": "थनैला रोग से बचाव के लिए दुहने के बाद 0.5% आयोडीन घोल में थनों को डुबोएं (टीट डिपिंग)।",
    "cow-focus-3": "मानसून की शुरुआत और मानसून के बाद पेट के कीड़ों की दवा (कृमिनाशक) अवश्य दें।",
    "buf-anim-title": "दुधारू भैंस (महिष)",
    "buf-anim-desc": "भैंसें अधिक वसा (फैट) युक्त गाढ़ा दूध देती हैं जो मावा और घी के लिए उत्तम है। वे मोटा सूखा चारा पचाने में सक्षम हैं, लेकिन पसीने की ग्रंथियां कम होने के कारण उन्हें गर्मी से बचाना (नहलाना या पानी छिड़कना) और मूक मद की पहचान करना बहुत जरूरी है।",
    "buf-fact-gest": "305 - 315 दिन",
    "buf-fact-water": "80 - 110 लीटर",
    "buf-fact-temp": "38.0°C (100.5°F)",
    "buf-fact-prod": "गाढ़ा दूध (7-8% वसा)",
    "buf-focus-1": "गर्मी प्रबंधन: दोपहर में पानी का छिड़काव, पंखे या छायादार तालाब में नहलाने की व्यवस्था।",
    "buf-focus-2": "मूक मद (साइलेंट हीट) की पहचान सुबह (5-7 बजे) और देर शाम ध्यानपूर्वक करें।",
    "buf-focus-3": "मानसून से पहले गलघोंटू (HS) का टीका अनिवार्य रूप से लगवाएं।",
    "goat-anim-title": "घरेलू बकरी (अजा)",
    "goat-anim-desc": "'गरीब की गाय' कही जाने वाली बकरी कम लागत में अधिक लाभ देती है। वे झाड़ियों और पेड़ों की पत्तियां चाव से खाती हैं, लेकिन नम और गीले फर्श से उन्हें बचाना जरूरी है क्योंकि नमी से खुर सड़न (फुट रॉट) और निमोनिया होता है।",
    "goat-fact-gest": "145 - 152 दिन",
    "goat-fact-water": "5 - 10 लीटर",
    "goat-fact-temp": "39.0°C (102.5°F)",
    "goat-fact-prod": "दूध, मेमने व मांस",
    "goat-focus-1": "गोशाला को पूरी तरह सूखा रखने के लिए ऊंचा बांस या लकड़ी का मचान फर्श बनाएं।",
    "goat-focus-2": "वार्षिक पीपीआर (बकरी प्लेग) का टीका और हर 6 माह में फड़किया (ET) का बूस्टर लगवाएं।",
    "goat-focus-3": "खुरपका (फुट रॉट) रोकने के लिए हर महीने खुरों की जांच और कटाई (ट्रिमिंग) करें।",
    "sheep-anim-title": "घरेलू भेड़ (मेष)",
    "sheep-anim-desc": "भेड़ें झुंड में चरने वाली सहनशील पशु हैं जो बंजर चरागाहों और खेतों की खूंटी से कीमती ऊन, मांस और उत्तम जैविक खाद बनाती हैं। उन्हें बारिश की नमी से बचाना और खुर सड़न से बचाव के लिए फुटबाथ करवाना आवश्यक है।",
    "sheep-fact-gest": "145 - 150 दिन",
    "sheep-fact-water": "4 - 8 लीटर",
    "sheep-fact-temp": "39.0°C (102.0°F)",
    "sheep-fact-prod": "ऊन, मांस व जैविक खाद",
    "sheep-focus-1": "ऊन कतरने के 2-3 हफ्ते बाद जूं, चिंचोके और पिस्सू से बचाव के लिए दवा में नहलाएं (डिपिंग)।",
    "sheep-focus-2": "केवल भेड़-सुरक्षित खनिज मिश्रण ही दें (भेड़ें तांबे के प्रति बहुत संवेदनशील होती हैं)।",
    "sheep-focus-3": "मानसून से पहले फड़किया रोग (एंटेरोटॉक्सीमिया) का टीका अवश्य लगवाएं।",
    "husbandry-tag": "सर्वोत्तम प्रबंधन पद्धतियां",
    "husbandry-title": "स्वस्थ पशुपालन के 4 आधार स्तंभ",
    "husbandry-subtitle": "दैनिक आदतें जो 80% रोके जा सकने वाले संक्रामक और पाचन रोगों से बचाती हैं।",
    "pillar1-title": "1. साफ व हवादार गोशाला आवास",
    "pillar1-desc": "गोशाला में उचित ढलान, सूखा फर्श और पर्याप्त ताजी हवा निमोनिया, थनैला और परजीवियों के पनपने को रोकती है।",
    "pillar2-title": "2. पर्याप्त स्वच्छ पेयजल",
    "pillar2-desc": "पशुओं को प्रति लीटर दूध उत्पादन के लिए 4 से 5 लीटर स्वच्छ पानी चाहिए। पानी की खेलियों को सप्ताह में दो बार अवश्य धोएं।",
    "pillar3-title": "3. दैनिक जुगाली व स्वास्थ्य निगरानी",
    "pillar3-desc": "प्रतिदिन 6 से 8 घंटे जुगाली करना स्वस्थ पेट की सबसे बड़ी पहचान है। सुस्ती या कान लटकना बीमारी का पहला संकेत है।",
    "pillar4-title": "4. सख्त जैव-सुरक्षा एवं संगरोध (क्वारंटाइन)",
    "pillar4-desc": "नए खरीदे पशु को 21 दिनों तक अलग रखें, गोशाला के प्रवेश द्वार पर चूने का फुटबाथ रखें और समय पर टीके लगवाएं।",
