    "dis-banner-title": "पशुधन रोग मार्गदर्शिका",
    "dis-banner-subtitle": "सामान्य स्वास्थ्य समस्याओं, लक्षणों, रोकथाम के उपायों को समझें और जानें कि कब पशु चिकित्सक को तत्काल बुलाना अनिवार्य है।",
    "dis-disc-title": "चिकित्सा एवं निदान अस्वीकरण",
    "dis-disc-text": "यह जानकारी केवल शैक्षणिक और जागरूकता के उद्देश्य से है, इसे पेशेवर पशु चिकित्सा का विकल्प न समझें। डॉक्टर की सलाह के बिना कभी भी एंटीबायोटिक या चीरा-फाड़ी न करें। यदि पशु अत्यधिक दर्द में हो, चारा खाना छोड़ दे या तेज बुखार हो, तो तुरंत पंजीकृत डॉक्टर को बुलाएं।",
    "dis-search-placeholder": "रोग या लक्षण खोजें (उदा. खुरपका, थनैला, बुखार, लार गिरना, छाले, गलघोंटू, चिंचोके)...",
