    "cp-deworm-title": "3. समय पर पेट के कीड़ों की दवा (कृमिनाशक)",
    "cp-deworm-desc": "साल में 3 बार (मानसून से पहले, बाद में और सर्दी में) कृमिनाशक दें। दवा बदल-बदल कर दें ताकि कीड़े दवा के प्रति प्रतिरोधी न बनें।",
    "cp-bio-title": "4. बाड़े की जैव-सुरक्षा एवं संगरोध",
    "cp-bio-desc": "बाहर से लाए गए नए पशुओं को कम से कम 21 दिनों तक अलग बाड़े में रखें ताकि कोई छुपा हुआ संक्रामक रोग घर के पशुओं में न फैले।",
    "cp-udder-title": "5. अयन (थनों) की सख्त स्वच्छता",
    "cp-udder-desc": "दूध दुहने से पहले थनों को लाल दवा के गुनगुने पानी से धोएं और पोंछें। दुहने के बाद थनों को आयोडीन घोल में डुबोएं।",
    "cp-stress-title": "6. सर्दी और गर्मी से बचाव",
