    "chk-item-1": "सुबह के समय सभी वयस्क गायों और भैंसों की जुगाली (पगुरी) की जांच करें।",
    "chk-item-2": "पानी की खेलियों को अच्छी तरह रगड़कर धोएं और ताजा, स्वच्छ पानी भरें।",
    "chk-item-3": "दूध दुहने वाले के हाथ और गाय के थनों को दुहने से पहले लाल दवा के पानी से धोएं।",
    "chk-item-4": "भेड़-बकरियों के खुरों की जांच करें कि कहीं बदबू, सड़न या लंगड़ापन तो नहीं है।",
    "chk-item-5": "पशु के कानों के पीछे, पूंछ के नीचे और त्वचा की सिलवटों में चिंचोके/किलनी की जांच करें।",
