    "aim-4-desc": "ग्रामीण डेयरी किसानों को योग्य पशु चिकित्सकों और आपातकालीन एम्बुलेंस सुविधाओं से जोड़ना।",
    "about-scope-title": "🚀 भविष्य का दायरा एवं तकनीकी दृष्टिकोण",
    "about-scope-desc": "फ्रंटएंड को स्वच्छ, मॉड्यूलर संरचना के साथ बनाया गया है जो भविष्य में बड़े स्तर पर विस्तार के लिए तैयार है:",
    "scope-1-desc": "पायथन फ्लास्क / फास्टएपीआई बैकएंड: पशु रिकॉर्ड और डॉक्टर अपॉइंटमेंट बुकिंग के लिए गतिशील REST एंडपॉइंट्स।",
    "scope-2-desc": "माइएसक्यूएल रिलेशनल डेटाबेस: पशु, रोग, राशन, रिमाइंडर और सत्यापित क्लीनिकों के लिए स्थायी डेटाबेस।",
    "scope-3-desc": "गूगल मैप्स एपीआई: निकटतम पशु चिकित्सालय तक पहुंचने के लिए वास्तविक समय में जीपीएस दूरी और दिशा-निर्देश।",
    "scope-4-desc": "एआई रोग लक्षण पहचान: लंपी त्वचा रोग जैसी बीमारियों के लिए मोबाइल कैमरे से फोटो विश्लेषण।",
    "scope-5-desc": "ऑफलाइन पीडब्ल्यूए (PWA) सपोर्ट: बिना इंटरनेट वाले ग्रामीण क्षेत्रों में भी आहार तालिकाओं को देखने की सुविधा।",
    "academic-context-note": "शैक्षणिक संदर्भ: अंतिम वर्ष बी.टेक / बी.एससी कंप्यूटर साइंस एवं कृषि सूचना विज्ञान प्रोजेक्ट (2025–2026)।",
