    "faq-tag": "अक्सर पूछे जाने वाले प्रश्न",
    "faq-title": "किसान एवं उपयोगकर्ता सहायता केंद्र",
    "faq-subtitle": "मंच के उपयोग, चिकित्सा अस्वीकरण और पशु चिकित्सा सहायता संबंधी प्रश्नों के त्वरित उत्तर।",
    "faq-q1": "क्या स्मार्ट एनिमल केयर का उपयोग पूरी तरह से निःशुल्क है?",
    "faq-a1": "हाँ, स्मार्ट एनिमल केयर एक खुला, निःशुल्क शैक्षणिक मंच है जो कॉलेज प्रस्तुति और किसानों के सशक्तिकरण के लिए विकसित किया गया है। सभी गाइड, कैलकुलेटर, रिमाइंडर टूल और क्लीनिक निर्देशिका बिना किसी शुल्क के 100% उपलब्ध हैं।",
    "faq-q2": "क्या मैं इस वेबसाइट का उपयोग करके अपनी बीमार गाय का खुद इलाज कर सकता हूँ?",
    "faq-a2": "बिल्कुल नहीं। यह मंच केवल जागरूकता बढ़ाने, लक्षणों की शीघ्र पहचान करने और निवारक देखभाल के लिए है। रोगों का सटीक निदान, एंटीबायोटिक दवाएं और सर्जरी केवल पंजीकृत पशु चिकित्सक द्वारा ही की जानी चाहिए। अपने आप दवा देने से पशु की जान जा सकती है।",
    "faq-q3": "टीकाकरण रिमाइंडर टूल कैसे काम करता है?",
    "faq-a3": "यह रिमाइंडर टूल आपके वेब ब्राउज़र के आधुनिक लोकल स्टोरेज (localStorage) का उपयोग करता है। जब आप कोई शेड्यूल जोड़ते हैं, तो यह आपके फोन या कंप्यूटर पर सुरक्षित हो जाता है। पेज बंद करने या रिफ्रेश करने पर भी आपका डेटा सुरक्षित रहता है!",
    "faq-q4": "पशु की गंभीर आपातकालीन स्थिति में मुझे तुरंत क्या करना चाहिए?",
    "faq-a4": "गंभीर अफरा, कठिन प्रसव, तेज खून बहना, पशु का अचानक गिर जाना या गले की सूजन के साथ तेज बुखार होने पर तुरंत राष्ट्रीय पशु एम्बुलेंस 1962 पर कॉल करें या हमारी निर्देशिका से नजदीकी पशु चिकित्सालय से संपर्क करें।",
    "faq-q5": "कोई पशु चिकित्सक या क्लीनिक इस निर्देशिका में अपना विवरण कैसे जोड़ सकता है?",
    "faq-a5": "चिकित्सक ऊपर दिए गए फॉर्म के माध्यम से अपने क्लीनिक का नाम, पंजीकरण संख्या, डिग्री, पता और समय भेज सकते हैं। भविष्य के बैकएंड अपडेट में प्रत्यक्ष ऑनलाइन पंजीकरण पोर्टल प्रदान किया जाएगा।",
    "modal-success-title": "पूछताछ सफलतापूर्वक दर्ज की गई!",
    "modal-success-desc": "स्मार्ट एनिमल केयर टीम से संपर्क करने के लिए धन्यवाद। आपके फॉर्म का क्लाइंट साइड सत्यापन सफलतापूर्वक पूर्ण हुआ।",
    "modal-success-note": "प्रदर्शन नोट: लाइव उत्पादन प्रणाली में यह फॉर्म पायथन फ्लास्क बैकएंड एपीआई को डेटा भेजता है और व्यवस्थापक को ईमेल सूचना प्रेषित करता है।",
    "modal-success-btn": "मंच का अवलोकन जारी रखें",
