    "anim-cow-sci": "बॉस टॉरस / बॉस इंडिकस",
    "anim-buf-sci": "बुबालस बुबालिस",
    "anim-goat-sci": "कैप्रा हिरकस",
    "anim-sheep-sci": "ओविस एरीज़",
    "anim-buf-desc-p": "मक्खन वसा (7-8% फैट) से भरपूर गाढ़े दूध के लिए प्रसिद्ध, मुर्रा, नीली-रावी और मेहसाणा जैसी भैंसें मोटे चारे को पचाने में माहिर हैं। कम पसीने की ग्रंथियां और काली त्वचा के कारण उन्हें गर्मी से विशेष बचाव की जरूरत होती है।",
    "anim-buf-prod-val": "अधिक फैट वाला दूध व खेती कार्य",
    "anim-buf-focus-1": "भीषण गर्मी में दिन में दो बार साफ पानी में नहलाएं या पानी का छिड़काव करें।",
    "anim-buf-focus-2": "दूध दुहने से पहले और बाद में थनों के चौड़े छिद्रों की कीचड़ और गंदगी से जांच करें।",
    "anim-buf-focus-3": "सुबह और शाम के समय मूक मद (साइलेंट हीट) के लक्षणों पर विशेष नजर रखें।",
    "anim-goat-desc-p": "किसान की सच्ची साथी या 'गरीब की गाय' कही जाने वाली बकरियां सूखा-सहनशील और झाड़ियां चरने वाली पशु हैं। जमुनापारी, ब्लैक बंगाल और सिरोही जैसी नस्लें कम पूंजी में पौष्टिक दूध और मांस देती हैं।",
    "anim-goat-temp-val": "39.0°C (102.2°F)",
    "anim-goat-prod-val": "मांस, दूध एवं मेमने",
    "anim-goat-focus-1": "बाड़े के फर्श को जमीन से ऊंचा और बिल्कुल सूखा रखें; बकरियां कीचड़ और गीलेपन को बर्दाश्त नहीं कर सकतीं।",
    "anim-goat-focus-2": "संक्रामक खुर सड़न से बचाव के लिए बढ़े हुए खुरों की नियमित कटाई करें।",
    "anim-goat-focus-3": "पीपीआर (बकरी प्लेग) और फिड़किया (ईटी) के टीकाकरण कैलेंडर का कड़ाई से पालन करें।",
    "anim-sheep-desc-p": "भेड़ें जमीन से सटाकर चरती हैं और बची हुई खूंटी, सूखी घास व पहाड़ी चरागाहों का बेहतरीन उपयोग करती हैं। मारवाड़ी, दक्कनी और नेल्लोर जैसी नस्लें ऊन, मांस और खाद देती हैं, लेकिन भीगी ऊन से ठंड लगने से इनका बचाव जरूरी है।",
    "anim-sheep-prod-val": "मांस, मोटी ऊन एवं खाद",
    "anim-sheep-focus-1": "गर्मी और ठंड शुरू होने से पहले साल में ऊन की कटाई करें ताकि पशु तनावमुक्त और साफ रहे।",
    "anim-sheep-focus-2": "ऊन कतरने के 2-3 सप्ताह बाद किलनी व जूं की रोकथाम के लिए दवा के घोल में डुबकी (डिपिंग) लगाएं।",
    "anim-sheep-focus-3": "भेड़ों को गाय वाले कॉपर युक्त खनिज मिश्रण न दें; तांबे की अधिकता भेड़ों के लिए जानलेवा होती है।",
