    "dis-fmd-warn-p": "रोग फैलते ही तुरंत सरकारी पशु चिकित्सालय को सूचित करें। 6 माह से छोटे बछड़ों में बिना छाले दिखे हृदय की विफलता (टाइगर हार्ट) से अचानक मृत्यु हो सकती है।",
    "dis-btn-find-vet-near": "अपने नजदीकी पशु चिकित्सक खोजें →",
    "dis-btn-contact-vet-urgently": "तुरंत पशु चिकित्सक से संपर्क करें →",
    "dis-btn-emergency-assist": "आपातकालीन चिकित्सा सहायता खोजें →",
    "dis-btn-report-dispensary": "नजदीकी अस्पताल में रिपोर्ट करें →",
    "dis-hs-warn-p": "आपातकाल! 12 से 36 घंटे के भीतर मृत्यु हो सकती है। बुखार के शुरुआती चरण में ही पशु चिकित्सक द्वारा नसों में एंटीबायोटिक (सल्फा ड्रग्स/ऑक्सीटेट्रासाइक्लिन) लगाना अनिवार्य है।",
    "dis-mast-warn-p": "दूध में छीछड़े या थन में कड़ापन दिखते ही तुरंत डॉक्टर को बुलाएं। देरी से थन हमेशा के लिए बेकार हो जाता है। थन में दवा चढ़ाने से पहले जांच करवाएं।",
    "dis-lsd-warn-p": "दर्द और निमोनिया से बचाव के लिए पशु चिकित्सक से सूजनरोधी इंजेक्शन लगवाएं। सांस लेने में कठिनाई या गले में गांठें होने पर आपातकालीन उपचार जरूरी है।",
    "dis-bq-warn-p": "कुछ ही घंटों में आपातकालीन उपचार आवश्यक है। विष फैलने से पहले पशु चिकित्सक द्वारा पेनिसिलिन एंटीबायोटिक मांसपेशियों में लगाना जीवन रक्षक है।",
    "dis-ppr-warn-p": "असुरक्षित बकरियों में 80% तक मृत्यु हो सकती है। निर्जलीकरण रोकने के लिए ग्लूकोज ड्रिप, निमोनिया के लिए एंटीबायोटिक और सूजनरोधी दवाएं अत्यंत आवश्यक हैं।",
    "dis-bloat-warn-p": "गंभीर आपातकाल: तीव्र अफरा फेफड़ों को दबा देता है, जिससे 1-2 घंटे में दम घुटने से मौत हो सकती है। डॉक्टर द्वारा पेट की नली या ट्रोकार-कैन्युला से गैस निकालना आवश्यक है।",
    "dis-anthrax-warn-p": "तुरंत सरकारी पशु चिकित्सालय को सूचित करें। यह मनुष्यों में भी फैल सकता है (जूनोटिक)। संपर्क में आए अन्य पशुओं को तुरंत बचाव टीका व दवा दी जानी चाहिए।",
    "dis-bab-warn-p": "लाल रक्त कोशिकाओं के तेजी से नष्ट होने से गंभीर खून की कमी होती है। डॉक्टर द्वारा तुरंत विशिष्ट प्रोटोजोआ-रोधी इंजेक्शन (डिमिनाजीन या इमिडोकार्ब) लगवाना अनिवार्य है।",
    "dis-et-warn-p": "जीवाणु द्वारा बनाया गया जहर बहुत तेजी से काम करता है। शुरुआती लक्षण दिखते ही डॉक्टर द्वारा एंटीसीरम और दर्द निवारक इंजेक्शन लगवाना चाहिए।",
