    "vet-map-desc": "इस शैक्षणिक प्रोटोटाइप में जीपीएस निर्देशांक प्रदर्शित किए गए हैं। जब बैकएंड डेटाबेस जोड़ा जाएगा, तब यह गूगल मैप्स एपीआई या ओपन-स्ट्रीट-मैप से सीधे जुड़ जाएगा।",
