    "nut-p3-title": "3. संतुलित पशु आहार (दाना मिश्रण)",
    "nut-p3-desc": "दूध उत्पादन और शारीरिक वृद्धि की उच्च ऊर्जा और प्रोटीन जरूरतों को पूरा करता है।",
    "nut-p3-grain": "ऊर्जा वाले अनाज (35-40%):",
    "nut-p3-cake": "खलियां (30-35%):",
    "nut-p3-bran": "चोकर व रेशेदार भाग (25-30%):",
    "nut-p4-title": "4. खनिज लवण एवं सादा नमक",
    "nut-p4-desc": "प्रजनन क्षमता, मद के सही समय पर आने, रोग प्रतिरोधक क्षमता और दूध उतारने के लिए अनिवार्य।",
    "nut-p5-title": "5. स्वच्छ पीने का पानी",
    "nut-p5-desc": "दूध में 87% पानी होता है! पानी सबसे सस्ता लेकिन अक्सर नजरअंदाज किया जाने वाला पोषक तत्व है।",
    "nut-golden-title": "पशु आहार के सुनहरे नियम",
    "nut-golden-desc": "नियमित आहार समय-सारणी से रुमेन में चारे का पाचन सर्वोत्तम होता है।",
    "nut-tab-all-btn": "सभी पशु",
    "nut-tab-cow-btn": "गाय / गोवंश",
    "nut-tab-buffalo-btn": "भैंस",
    "nut-tab-goat-btn": "बकरी",
    "nut-tab-sheep-btn": "भेड़",
    "care-p1-title": "1. स्वच्छ एवं हवादार आवास",
    "care-p1-desc": "नमी और अमोनिया गैस से निमोनिया और थनैला रोग होता है। छत 10-12 फीट ऊंची और हवादार रखें। फर्श में 1:40 का ढलान दें ताकि पेशाब तुरंत बाहर बह जाए।",
    "care-p2-title": "2. बाड़े की नियमित स्वच्छता एवं कीटाणुशोधन",
    "care-p2-desc": "गोबर दिन में दो बार हटाएं। हफ्ते में एक बार फर्श पर चूना छिड़कें। प्रवेश द्वार पर पोटैशियम परमैंगनेट का फुटबाथ बनाएं ताकि बाहर से बीमारी न आए।",
    "care-p3-title": "3. समय पर टीकाकरण अनुसूची",
    "care-p3-desc": "टीके जानलेवा महामारियों से बचाते हैं। तेज बुखार, अत्यधिक कमजोर या पेट के कीड़ों से पीड़ित पशु को टीका न लगाएं, क्योंकि उसमें इम्युनिटी नहीं बनेगी।",
    "care-p4-title": "4. मौसमी कृमिनाशक एवं स्वास्थ्य जांच",
    "care-p4-desc": "साल में 3-4 बार (मानसून से पहले और बाद में) पेट के कीड़ों की दवा दें। दवा बदलते रहें ताकि कीड़ों में दवा के प्रति प्रतिरोधक क्षमता न बने।",
    "care-p5-title": "5. निरंतर स्वच्छ पेयजल व्यवस्था",
    "care-p5-desc": "छायादार हौज में हमेशा ताजा पानी उपलब्ध रखें। काई लगे गंदे पानी से लीवर फ्लूक्स और लेप्टोस्पायरोसिस होता है। हर 10 दिन में हौज को ब्लीचिंग पाउडर से साफ करें।",
    "care-p6-title": "6. प्रारंभिक पहचान एवं संगरोध (क्वारंटाइन)",
    "care-p6-desc": "सुबह दुहते समय पशु के व्यवहार पर ध्यान दें। दूध घटना, कान लटकना, सूखी थूथन या रवंथ बंद होना शुरुआती संकेत हैं। बीमार या नए पशु को तुरंत अलग बाड़े में रखें।",
    "care-chk-title": "📋 दैनिक एवं साप्ताहिक फार्म जैवसुरक्षा चेकलिस्ट",
    "care-chk-sub": "अपने दैनिक फार्म कार्यों को पूरा करते समय प्रत्येक पर क्लिक करें और स्कोर देखें!",
    "care-chk-1-title": "पानी की खेल / हौज जांचें:",
    "care-chk-1-desc": "साफ किया गया, ठंडा पीने योग्य पानी भरा गया, पक्षियों की बीट और काई से मुक्त।",
    "care-chk-2-title": "रवंथ (जुगाली) का निरीक्षण:",
    "care-chk-2-desc": "जांच की गई कि आराम कर रहे पशु नियमित जुगाली कर रहे हैं।",
    "care-chk-3-title": "गोबर हटाना एवं सूखा बिछावन:",
    "care-chk-3-desc": "नालियां साफ की गईं; अधिक दूध देने वाली गायों के नीचे सूखा बिछावन डाला गया।",
    "care-chk-4-title": "दुहने के बाद थन कीटाणुशोधन:",
    "care-chk-4-desc": "थनों को 0.5% आयोडीन घोल में डुबोया गया; दुहने के बाद 45 मिनट खड़ा रखा।",
    "care-chk-5-title": "चिंचोके एवं मक्खी जांच:",
    "care-chk-5-desc": "चिंचोके और मक्खी के लिए त्वचा, पूंछ की जड़ और कानों की जांच की।",
    "care-chk-6-title": "चारा गुणवत्ता जांच:",
    "care-chk-6-desc": "साइलेज और अनाज के डिब्बों में फफूंद, नमी या जाले की जांच की गई।",
    "care-cal-tag": "मानक प्रोटोकॉल",
