    "mast-name-title": "थनैला रोग (मैस्टाइटिस)",
    "mast-vernacular-text": "स्थानीय नाम: थनैला / बादी",
    "lsd-name-title": "लंपी त्वचा रोग (LSD)",
    "lsd-vernacular-text": "स्थानीय नाम: लंपी रोग",
    "bq-name-title": "लंगड़ा बुखार (BQ / ब्लैक क्वार्टर)",
    "bq-vernacular-text": "स्थानीय नाम: जहरबाद / लंगड़िया",
    "ppr-name-title": "पीपीआर (बकरी प्लेग)",
    "ppr-vernacular-text": "स्थानीय नाम: बकरी प्लेग / महामारी",
    "bloat-name-title": "तीव्र अफरा / पेट फूलना",
    "bloat-vernacular-text": "स्थानीय नाम: अफरा / पेट फूलना",
    "anthrax-name-title": "एंथ्रेक्स (गिल्टी रोग)",
    "anthrax-vernacular-text": "स्थानीय नाम: गिल्टी रोग / चिरचिटा",
    "bab-name-title": "बबेसिओसिस (लाल पेशाब / चिचड़ी बुखार)",
    "bab-vernacular-text": "स्थानीय नाम: लाल पेशाब बुखार",
    "et-name-title": "एंटेरोटॉक्सीमिया (फिड़किया रोग)",
    "et-vernacular-text": "स्थानीय नाम: फिड़किया रोग",
    "hs-prev-text": "मानसून से पहले (मई-जून) में वार्षिक गलघोंटू का एलम टीका अनिवार्य रूप से लगवाएं। प्रकोप के समय भारी बारिश या दलदली चरागाहों में बैलों से काम न लें।",
    "hs-firstaid-text": "बीमार पशु को ठंडी, सूखी जगह पर अलग रखें। सांस की नली खुली रहे इसलिए सिर ऊंचा रखें। गले में सूजन के कारण जबरन तरल दवा न पिलाएं, इससे फेफड़ों में पानी जा सकता है।",
    "mast-prev-text": "दुहने के बाद थनों को आयोडीन में डुबोएं। दुहने की जगह बिल्कुल साफ रखें। दुहने के तुरंत बाद ताजा चारा दें ताकि गाय 30-45 मिनट खड़ी रहे और थन का छिद्र बंद हो सके।",
    "mast-firstaid-text": "संक्रमित थन से हर 2 घंटे में खराब दूध किसी बर्तन में निकालें और नष्ट करें। सूजन कम करने के लिए बर्फ या ठंडे पानी की पट्टी लगाएं।",
    "lsd-prev-text": "गोट पॉक्स या लंपी वैक्सीन का टीका लगवाएं। नीम के तेल का छिड़काव और मक्खी-मच्छर-चिंचोके का कड़ा नियंत्रण रखें। नए पशुओं को अलग रखें।",
    "lsd-firstaid-text": "फूटी हुई गांठों को बीटाडीन से साफ करें और मक्खी भगाने वाला मरहम लगाएं। मुलायम हरी घास, गुड़-इलेक्ट्रोलाइट का पानी और हल्दी-आंवला दें।",
    "bq-prev-text": "मानसून से पहले मई में 6 माह से बड़े बछड़ों का वार्षिक टीकाकरण कराएं। खोदी गई मिट्टी वाली जगहों पर पशुओं को न चराएं जहां बीजाणु दशकों तक रहते हैं।",
    "bq-firstaid-text": "पशु को तुरंत अलग करें और नरम बिछावन दें। सूजन पर कभी चीरा न लगाएं, इससे जीवाणु फैलकर जमीन को हमेशा के लिए दूषित कर देते हैं।",
    "ppr-prev-text": "3-4 माह की उम्र में पीपीआर का टीका लगवाएं जो 3 साल तक सुरक्षा देता है। बाजार से खरीदी गई नई बकरियों को 15 दिनों तक अलग रखें।",
    "ppr-firstaid-text": "आंख और नाक की पपड़ी को गुनगुने नमक के पानी से साफ करें। मुंह के छालों को लाल दवा से धोएं। दस्त से बचाव के लिए ओआरएस (ORS) का घोल पिलाएं।",
    "bloat-prev-text": "भूखे पशु को ओस लगे बरसीम या लूसर्न के खेत में न छोड़ें। हरा चारा देने से पहले सूखा भूसा खिलाएं। दाने में अचानक बदलाव न करें।",
    "bloat-firstaid-text": "मुंह में लकड़ी की लगाम बांधें ताकि लार गिरे और डकार आए। पशु को चढ़ाई पर धीरे-धीरे चलाएं। 200-300 मिली मीठा तेल (सरसों या मूंगफली का तेल) पिलाएं।",
    "anthrax-prev-text": "रोग प्रभावित क्षेत्रों में वार्षिक टीका लगवाएं। एंथ्रेक्स से मरे पशु के शव को कभी न चीरें या खाल न उतारें; हवा लगने से बीजाणु 50 वर्षों तक जमीन में जीवित रहते हैं।",
    "anthrax-firstaid-text": "शरीर से निकले तरल को न छुएं! मृत पशु को 6-8 फीट गहरे गड्ढे में चूना डालकर दफनाएं या सुरक्षित रूप से जलाएं।",
    "bab-prev-text": "पशुओं और बाड़े की दीवारों पर चिंचोके मारने की दवा (डेल्टामेथ्रिन/अमिट्राज) का नियमित छिड़काव करें। किलनी मुक्त झुंड बनाए रखें।",
    "bab-firstaid-text": "बीमार पशु को छाया में रखें। गुड़ का पानी और मुलायम हरी घास दें। दस्ताने पहनकर चिंचोके हटाएं।",
    "et-prev-text": "प्रसव से 2-4 सप्ताह पहले गाभिन मादा और 2 माह के मेमनों को टीका लगवाएं। अचानक अधिक दाना या नया हरा चारा न दें।",
    "et-firstaid-text": "तुरंत भारी दाना और हरा चारा रोकें। सूखा भूसा दें और पेट का एसिड कम करने के लिए खाने का सोडा (मीठा सोडा) पानी में घोलकर पिलाएं।",
