    "nut-p1-sil-items": "किण्वित मक्का के डंठल सूखे मौसम के लिए पोषक तत्वों को सुरक्षित रखते हैं।",
    "nut-p2-wheat-desc": "उत्कृष्ट सूखा चारा आधार।",
    "nut-p2-paddy-desc": "प्रोटीन की मात्रा बढ़ाने के लिए यूरिया-शीरे से उपचारित करें।",
    "nut-p2-chaff-desc": "अपव्यय रोकने और पशु की ऊर्जा बचाने के लिए चारे को 1-2 इंच की कुट्टी में काटें।",
    "nut-p3-grain-desc": "मक्का, जौ, दलिया (गेहूं)।",
    "nut-p3-cake-desc": "सरसों, बिनौला, मूंगफली या सोयाबीन की खल।",
    "nut-p3-bran-desc": "गेहूं का चोकर, चावल की पॉलिश, या डी-ऑयल्ड केक।",
    "nut-p4-min1": "दैनिक खनिज मिश्रण: गाय/भैंस के लिए 50-60 ग्राम; बकरी/भेड़ के लिए 10-15 ग्राम।",
    "nut-p4-min2": "गोठों में खनिज युक्त नमक की ईंट लटकाएं ताकि पशु आवश्यकतानुसार चाट सकें।",
    "nut-p4-min3": "कैल्शियम और फास्फोरस का 2:1 अनुपात प्रसव के बाद मिल्क फीवर से बचाता है।",
    "nut-p5-wat1": "दुधारू गाय को प्रति लीटर दूध उत्पादन पर 3-4 लीटर पानी की आवश्यकता होती है।",
    "nut-p5-wat2": "पानी कोलीफॉर्म बैक्टीरिया, भारी नाइट्रेट और काई के विषैले तत्वों से मुक्त होना चाहिए।",
    "nut-p5-wat3": "पानी की खुरलियों को साप्ताहिक रूप से साफ करें और पानी की टंकियों पर ठंडी छाया रखें।",
    "nut-golden-r1": "आहार में कभी भी अचानक बदलाव न करें; 7 से 10 दिनों में धीरे-धीरे बदलें।",
    "nut-golden-r2": "दाना आहार दो बराबर भागों में दें (सुबह और शाम दुहते समय)।",
    "nut-golden-r3": "खुरली को प्रतिदिन साफ करें; बासी, लार से भीगा या फफूंद लगा चारा निकाल दें।",
