    "nut-cow-focus-badge": "उच्च दुग्ध उत्पादन पर केंद्रित",
    "nut-cow-mgmt-desc": "उच्च दुग्ध देने वाली गाय को प्रारंभिक दुग्धकाल में ऊर्जा की कमी से बचाने के लिए निरंतर पोषण चाहिए (जो कीटोसिस का कारण बनता है)। प्रत्येक 2.5-3.0 लीटर दूध पर 1 किग्रा दाना, तथा 1.0-1.5 किग्रा जीवन निर्वाह दाना दें। संतुलित प्रोटीन और ऊर्जा के लिए दलहनी व गैर-दलहनी हरे चारे को 1:3 अनुपात में मिलाएं।",
