    "nut-buf-mgmt-desc": "भैंसें रेशेदार फसल अवशेषों को पचाने में माहिर होती हैं। चूंकि भैंस के दूध में 7-8% फैट होता है, इसलिए प्रति लीटर दूध पर ऊर्जा की आवश्यकता गाय से अधिक होती है। भैंस के प्रत्येक 2.0 लीटर दूध पर 1 किग्रा दाना दें। गर्मियों में ठंडा पानी और रात के समय खुरली में चारा दें।",
