    "dis-disc-text": "ही माहिती केवळ शैक्षणिक व जनजागृतीसाठी आहे, यास तज्ज्ञ पशुवैद्यकीय उपचारांचा पर्याय मानू नये. पशुवैद्यांच्या सल्ल्याशिवाय अँटिबायोटिक्स किंवा कोणतीही शस्त्रक्रिया करू नका. जनावर अत्यंत वेदनेत असल्यास, खाणे बंद केल्यास किंवा तीव्र ताप असल्यास तात्काळ नोंदणीकृत पशुवैद्यकाशी संपर्क साधा.",
