    "fmd-prev": "राष्ट्रीय पशु रोग नियंत्रण कार्यक्रमांतर्गत वर्षातून दोनदा (पावसाळ्यापूर्वी व नंतर) लसीकरण करा. नवीन जनावरांना २१ दिवस वेगळे ठेवा. गोठ्याच्या दारावर ४% कपडे धुण्याच्या सोड्याचे पाणी शिंपडा.",
    "fmd-firstaid": "तोंडातील फोड १% पोटॅशियम परमँगनेट (लाल औषध) किंवा तुरटीच्या पाण्याने धुवावेत. जिभेवर बोरो-ग्लिसरीन लावा आणि खुरांच्या जखमांमध्ये अळ्या पडू नयेत म्हणून कडुनिंबाचे तेल किंवा मलम लावावे. मऊ पेज किंवा लापशी खायला द्यावी.",
