    "hs-prev": "पावसाळ्यापूर्वी (मे-जून) घटसर्प लस टोचून घेणे बंधनकारक आहे. आजारी जनावराला तात्काळ वेगळे करा. पावसाळ्यात दलदलीच्या ठिकाणी जनावरांना चरण्यास सोडू नका.",
    "hs-firstaid": "जनावराला शांत, सावलीच्या व हवेशीर जागी ठेवा. घशात सूज असल्याने बाटलीने जबरदस्ती औषध किंवा पाणी पाजू नका, ते फुफ्फुसात जाऊन जनावर दगावू शकते.",
