    "bq-vernacular": "स्थानिक नाव: फऱ्या",
    "bq-prev": "पावसाळ्यापूर्वी ६ महिने ते २ वर्षे वयाच्या जनावरांचे लसीकरण करा. मृत जनावराची मातीत पुरून विल्हेवाट लावताना भरपूर चुना टाकावा जेणेकरून जंतू मातीत पसरणार नाहीत.",
    "bq-firstaid": "जनावराला मऊ बिछायतीवर ठेवा. सुजलेल्या भागावर गरम शेक देऊ नका, कारण उष्णतेमुळे विषारी घटक शरीरात वेगाने पसरतात.",
    "bq-vet": "गंभीर आपत्कालीन: स्नायूंमध्ये सड सुरू होण्यापूर्वी पशुवैद्यांकडून पेनिसिलिन आणि वेदनाशामक औषधोपचार त्वरित सुरू करणे आवश्यक आहे.",
    "mast-name": "स्तनदाह / मस्टायटीस (कासदाह)",
    "mast-vernacular": "स्थानिक नाव: स्तनदाह / मस्टायटीस",
    "mast-prev": "स्वच्छ दूध काढणी पद्धत: अंगठा न दुमडता पूर्ण हाताने दूध काढा, दूध काढल्यानंतर सड पोविडोन-आयोडीन द्रावणात बुडवा आणि जनावराला १५-२० मिनिटे बसू देऊ नका.",
    "mast-firstaid": "बाधित सडातून दर २-३ तासांनी खराब दूध भांड्यात काढून नष्ट करा (जमिनीवर सांडू नका). कासेवर सूज व दाह असल्यास थंड पाण्याच्या घड्या ठेवा.",
