    "ppr-prev": "पीपीआरची लस ३ वर्षांपर्यंत प्रतिकारशक्ती देते. ३ महिने वयाच्या सर्व करडांचे लसीकरण करा. आजार पसरल्यास नवीन शेळ्यांची खरेदी-विक्री थांबवा.",
