    "bloat-firstaid": "जनावराचे पुढील पाय उंचावर ठेवा जेणेकरून फुफ्फुसांवर ताण येणार नाही. फेस कमी करण्यासाठी २००-३०० मिली गोडेतेल आणि २० मिली तारपीन तेल एकत्र करून पाजा.",
    "bloat-vet": "अति-आपत्कालीन: जनावर धापा टाकत असल्यास, जीभ निळी पडल्यास किंवा तोल गेल्यास पशुवैद्यांकडून पोटात नळी घालून अथवा ट्रोकार कॅन्युलाने गॅस बाहेर काढणे आवश्यक आहे.",
