    "bruc-prev": "४ ते ८ महिने वयाच्या कालवडींना ब्रूसेला लस टोचून घ्या. मोठ्या गायींना किंवा बैलांना ही लस देऊ नका. कळपाची नियमित रक्त तपासणी करा.",
    "bruc-firstaid": "मानवामध्ये संसर्गाचा धोका: पडलेला गर्भ किंवा वार उघड्या हाताने हाताळू नका. हातमोजे वापरा आणि गर्भ चुन्यामध्ये खोल पुरून टाका.",
