    "pillar-water-desc": "दुधामध्ये ८७% पाणी असते! एका मोठ्या जनावराला दररोज ६० ते १०० लिटर पाणी लागते. गोठ्यात २४ तास थंड व स्वच्छ पाणी उपलब्ध असावे.",
