    "cow-nut-title": "🐄 दुभत्या गायींचे खाद्य व्यवस्थापन",
    "cow-nut-p1": "गायींसाठी चारा आणि दाण्याचे प्रमाण २:१ असावे. दररोज १५ लिटरपेक्षा जास्त दूध देणाऱ्या गायींना वितानंतर वजन घटू नये म्हणून १०० ग्रॅम बायपास फॅट द्यावे.",
