    "buf-nut-p1": "म्हशी सुका चारा चांगल्या प्रकारे पचवतात. म्हशीच्या दुधात ७-८% फॅट असल्याने दर २ लिटर दुधामागे १ किलो पशुखाद्य द्यावे.",
