    "goat-nut-p1": "शेळ्या झाडपाला आवडीने खातात. सुबाभूळ, कडुनिंब, बोर, पिंपळ यांचा पाला खाऊ घालावा, यातील घटकांमुळे पोटातील जंतांचे प्रमाण नैसर्गिकरित्या कमी राहते.",
