    "sheep-nut-p1": "मेंढ्या जमिनीलगतचे गवत चरतात. विणीच्या हंगामापूर्वी २ आठवडे मेंढ्यांना २०० ग्रॅम जादा दाणा दिल्यास (फ्लशिंग) जुळी करडे होण्याचे प्रमाण वाढते. खबरदारी: मेंढ्यांना कधीही गायीचे क्षार मिश्रण देऊ नका, कारण तांब्याच्या (कॉपर) विषबाधेचा मेंढ्यांना मोठा धोका असतो.",
    "tox-box-title": "⚠️ पशुखाद्य सुरक्षितता आणि विषबाधा धोक्याच्या सूचना",
    "tox-urea-title": "युरिया विषबाधा:",
