    "tox-hcn-desc": "पाण्याचा ताण बसलेली किंवा ४५ दिवसांपेक्षा लहान कोवळी ज्वारी जनावरांना खाऊ घालू नका, यात विषारी घटक असतो. पीक मोठे झाल्यावरच चारा म्हणून वापरावे.",
