    "care-disc-text": "लसीकरण वेळापत्रक आणि जंतनिर्मूलन औषधे स्थानिक हवामान, प्रादेशिक रोगांचा प्रादुर्भाव आणि शासकीय मार्गदर्शक तत्त्वांनुसार बदलू शकतात. लस देण्यापूर्वी नेहमी स्थानिक पशुवैद्यकीय अधिकाऱ्यांचा सल्ला घ्यावा.",
