    "faq-tag": "नेहमी विचारले जाणारे प्रश्न",
    "faq-title": "शेतकरी व वापरकर्ता मदत केंद्र",
    "faq-subtitle": "प्लॅटफॉर्मचा वापर, वैद्यकीय सूचना आणि पशुवैद्यकीय मदतीबाबतची झटपट उत्तरे.",
    "faq-q1": "स्मार्ट ॲनिमल केअर वापरणे पूर्णपणे मोफत आहे का?",
    "faq-a1": "होय, स्मार्ट ॲनिमल केअर हे कॉलेज सादरीकरण आणि शेतकरी सक्षमीकरणासाठी तयार केलेले पूर्णपणे मोफत शैक्षणिक व्यासपीठ आहे. सर्व माहिती, कॅल्क्युलेटर, रिमाइंडर साधने आणि दवाखान्यांची यादी कोणत्याही शुल्काशिवाय मोफत उपलब्ध आहे.",
    "faq-q2": "मी या वेबसाईटचा वापर करून माझ्या आजारी गायीवर स्वतः उपचार करू शकतो का?",
    "faq-a2": "नाही. हे व्यासपीठ केवळ जनजागृती, आजारांची सुरुवातीची लक्षणे ओळखणे आणि प्रतिबंधात्मक काळजी घेण्यासाठी आहे. रोगनिदान, अँटिबायोटिक्स देणे किंवा शस्त्रक्रिया यासाठी नोंदणीकृत पशुवैद्यकाकडून प्रत्यक्ष तपासणी आवश्यक असते. परस्पर औषध दिल्यास जनावराचा जीव धोक्यात येऊ शकतो.",
    "faq-q3": "लसीकरण स्मरणपत्र (रिमाइंडर) साधन कसे कार्य करते?",
    "faq-a3": "हे साधन आपल्या वेब ब्राऊझरमधील आधुनिक लोकल स्टोरेज (localStorage) तंत्रज्ञानाचा वापर करते. जेव्हा आपण लसीची तारीख नोंदवता, तेव्हा ती आपल्या फोन किंवा कॉम्प्युटरवर सुरक्षित राहते. पेज रिफ्रेश केले किंवा बंद केले तरी माहिती नष्ट होत नाही!",
    "faq-q4": "जनावरांच्या गंभीर आपत्कालीन परिस्थितीत त्वरित काय करावे?",
    "faq-a4": "तीव्र पोटफुगी, कठीण प्रसूती, रक्तस्राव, जनावर खाली पडणे किंवा घसा सुजून ताप आल्यास तात्काळ राष्ट्रीय पशु रुग्णवाहिका १९६२ वर कॉल करा किंवा आमच्या यादीतून जवळच्या पशुवैद्यकीय दवाखान्याशी संपर्क साधा.",
    "faq-q5": "पशुवैद्यक किंवा दवाखाना या डिरेक्टरीमध्ये आपली माहिती कशी जोडू शकतात?",
    "faq-a5": "डॉक्टर व दवाखाने वरील संपर्क फॉर्मद्वारे आपले नाव, नोंदणी क्रमांक, पदवी, पत्ता आणि वेळ पाठवू शकतात. पुढील अद्ययावत आवृत्तीत थेट ऑनलाईन नोंदणीची सुविधा उपलब्ध करून दिली जाईल.",
    "modal-success-title": "चौकशी यशस्वीरित्या नोंदवली गेली!",
    "modal-success-desc": "स्मार्ट ॲनिमल केअर टीमशी संपर्क साधल्याबद्दल धन्यवाद. आपल्या माहितीची पडताळणी यशस्वीरित्या पूर्ण झाली आहे.",
    "modal-success-note": "प्रात्यक्षिक टीप: प्रत्यक्ष प्रणालीमध्ये हा फॉर्म पायथन फ्लास्क बॅकएंडला माहिती पाठवून डेटाबेसमध्ये साठवतो आणि प्रशासकाला ईमेल पाठवतो.",
