    "anim-buf-desc-p": "उच्च फॅटयुक्त (७-८%) घट्ट दुधासाठी प्रसिद्ध असलेल्या मुऱ्हा, मेहसाणा आणि पंढरपुरी म्हशी निकृष्ट चोथा चारा चांगल्या प्रकारे पचवतात. त्यांना घाम ग्रंथी कमी असल्याने उन्हाळ्यात विशेष थंडाव्याची गरज असते.",
