    "anim-goat-desc-p": "'गरिबांची गाय' म्हणून ओळखली जाणारी शेळी अत्यंत काटक आणि झाडपाला खाऊन जगणारी आहे. उस्मानाबादी, संगमनेरी व सिरोही यांसारख्या जाती अत्यंत कमी खर्चात भरपूर दूध व मटन देतात.",
