    "anim-sheep-desc-p": "मेंढ्या जमिनीलगतचे गवत चरतात आणि कोरड्या गवताळ रानात उत्तम टिकतात. दख्खनी, माडग्याळ आणि मारवाडी जाती दर्जेदार लोकर, मटन व उत्तम खत देतात, परंतु ओल्या लोकरीमुळे त्यांना थंडी व न्यूमोनियापासून वाचवणे गरजेचे आहे.",
