    "dis-bq-warn-p": "काही तासांत आपत्कालीन उपचारांची गरज असते. स्नायूंमध्ये विष पसरण्यापूर्वी पशुवैद्यांकडून पेनिसिलिन इंजेक्शन देणे गरजेचे असते.",
    "dis-ppr-warn-p": "लसीकरण न केलेल्या शेळ्यांमध्ये मृत्यूदर ८०% पर्यंत जाऊ शकतो. तात्काळ सलाईन, न्यूमोनियासाठी अँटिबायोटिक्स देणे जीवनरक्षक ठरते.",
    "dis-bloat-warn-p": "अति-आपत्कालीन: पोटफुगीमुळे फुफ्फुसांवर दाब येऊन १-२ तासांत दम घुटून मृत्यू होऊ शकतो. पशुवैद्यांकडून नळी किंवा ट्रोकारने गॅस काढणे आवश्यक असते.",
    "dis-anthrax-warn-p": "शासकीय पशुवैद्यकीय अधिकाऱ्यांना तात्काळ कळवा. हा आजार माणसांमध्येही पसरतो. संपर्कातील इतर जनावरांना तातडीने प्रतिबंधक औषधे देणे गरजेचे आहे.",
    "dis-bab-warn-p": "लाल रक्तपेशी नष्ट झाल्याने रक्ताची तीव्र कमतरता होते. पशुवैद्यांकडून तात्काळ डिमिनाझिन किंवा इमिडोकार्ब इंजेक्शन देणे बंधनकारक असते.",
    "dis-et-warn-p": "जिवाणूंचे विष शरीरात वेगाने पसरते. सुरुवातीच्या टप्प्यात पशुवैद्यांकडून अँटीसीरम व वेदनाशामक इंजेक्शन देणे आवश्यक ठरते.",
