    "care-p1-title": "१. स्वच्छ व हवेशीर गोठा",
    "care-p1-desc": "गोठ्यातील ओल व अमोनिया वायूमुळे न्यूमोनिया आणि कासदाह होतो. छप्पर १०-१२ फूट उंच असावे. पाणी व मलमूत्र वाहून जाण्यासाठी जमिनीला योग्य उतार द्यावा.",
    "care-p2-title": "२. गोठा स्वच्छता व निर्जंतुकीकरण",
    "care-p2-desc": "दररोज दोनदा शेण काढावे. आठवड्यातून एकदा जमिनीवर चुना शिंपडावा. गोठ्याच्या प्रवेशद्वारावर लाल औषधाचा फुटबाथ ठेवावा जेणेकरून संसर्ग आत येणार नाही.",
    "care-p3-title": "३. वेळेवर लसीकरण वेळापत्रक",
    "care-p3-desc": "लसीकरणामुळे आजारांविरुद्ध प्रतिकारशक्ती तयार होते. ताप असलेल्या, अत्यंत अशक्त किंवा जंत झालेल्या जनावरांना लस टोचू नका.",
    "care-p4-title": "४. ऋतूनुसार जंतनिर्मूलन",
    "care-p4-desc": "वर्षातून ३-४ वेळा (पावसाळ्यापूर्वी व नंतर) जंतनिर्मूलन करा. जंतांमध्ये प्रतिकार तयार होऊ नये म्हणून दरवेळी जंतांचे औषध बदलून द्यावे.",
    "care-p5-title": "५. मुबलक व स्वच्छ पाणी",
    "care-p5-desc": "सावलीत पाण्याच्या टाक्यांमध्ये नेहमी ताजे पाणी असावे. शेवाळ साचलेल्या पाण्याने आजार होतात. दर १० दिवसांनी पाण्याची टाकी ब्लीचिंगने स्वच्छ करावी.",
    "care-p6-title": "६. आजाराची त्वरित ओळख व विलगीकरण",
    "care-p6-desc": "सकाळी दूध काढताना जनावराचे निरीक्षण करा. दूध कमी होणे, कान पाडणे किंवा रवंथ बंद होणे ही धोक्याची लक्षणे आहेत. नवीन किंवा आजारी जनावराला लगेच वेगळे ठेवा.",
    "care-chk-title": "📋 दैनंदिन व साप्ताहिक जैवसुरक्षा चेकलिस्ट",
    "care-chk-sub": "दैनंदिन गोठा कामे पूर्ण करताना टिक करा आणि तुमचा स्कोअर तपासा!",
    "care-chk-1-title": "पाण्याची टाकी तपासा:",
    "care-chk-1-desc": "स्वच्छ केले, थंड पिण्यायोग्य पाणी भरले, पक्ष्यांची विष्ठा व शेवाळमुक्त.",
    "care-chk-2-title": "रवंथ तपासणे:",
    "care-chk-2-desc": "विश्रांती घेणारी जनावरे नियमित रवंथ करत असल्याची खात्री केली.",
    "care-chk-3-title": "शेण काढणे व कोरडी बिछायत:",
    "care-chk-3-desc": "गटारे स्वच्छ केली; जास्त दूध देणाऱ्या गाईंखाली सुकी बिछायत टाकली.",
    "care-chk-4-title": "दूध काढल्यानंतर सड निर्जंतुकीकरण:",
    "care-chk-4-desc": "कास ०.५% आयोडीन द्रावणात बुडवली; दुभत्या जनावरांना ४५ मिनिटे उभे ठेवले.",
    "care-chk-5-title": "गोचीड व माश्यांची पाहणी:",
    "care-chk-5-desc": "गोचीड व माश्यांसाठी त्वचेच्या घड्या, शेपटीचा तळ व कान तपासले.",
