    "bloat-vernacular-text": "स्थानिक नाव: पोटफुगी / आफरा",
    "anthrax-name-title": "अँथ्रॅक्स / प्लीहा ज्वर",
    "anthrax-vernacular-text": "स्थानिक नाव: गिल्टी रोग",
    "bab-name-title": "बॅबेसियोसिस (लाल लघवी / गोचीड ताप)",
    "bab-vernacular-text": "स्थानिक नाव: लाल लघवी आजार",
    "et-name-title": "आंत्रविषार (फडकया रोग)",
    "et-vernacular-text": "स्थानिक नाव: फडकया आजार",
    "hs-prev-text": "पावसाळ्यापूर्वी (मे-जून) घटसर्प लस टोचून घेणे बंधनकारक आहे. आजाराचा प्रादुर्भाव असताना पावसाळ्यात किंवा दलदलीत जनावरांना राबवू नका.",
    "hs-firstaid-text": "आजारी जनावराला थंड व कोरड्या जागी वेगळे ठेवा. श्वास मोकळा व्हावा म्हणून डोके उंचावर ठेवा. घशात सूज असल्याने बाटलीने जबरदस्ती औषध पाजू नका.",
    "mast-prev-text": "दूध काढल्यानंतर सड आयोडीन द्रावणात बुडवावेत. गोठा स्वच्छ ठेवावा. दूध काढल्यानंतर जनावराला लगेच चारा द्यावा जेणेकरून ते ३०-४५ मिनिटे उभे राहील.",
    "mast-firstaid-text": "बाधित सडातून दर २ तासांनी खराब दूध काढून सुरक्षित नष्ट करा. कासेची सूज कमी करण्यासाठी बर्फ किंवा थंड पाण्याच्या घड्या ठेवा.",
    "lsd-prev-text": "गोट पॉक्स किंवा लंपी प्रतिबंधक लस टोचून घ्यावी. कडुनिंबाच्या तेलाची फवारणी करून गोचीड, डास व माश्यांचा कडक बंदोबस्त करावा.",
    "lsd-firstaid-text": "फुटलेल्या गाठी बिटाडीनने स्वच्छ करा व माश्या बसू नयेत म्हणून मलम लावा. कोवळा हिरवा चारा, गूळ-पाणी आणि हळद-आवळा प्रतिकारशक्तीसाठी द्या.",
    "bq-prev-text": "पावसाळ्यापूर्वी मे महिन्यात ६ महिन्यांवरील वासरांचे लसीकरण करा. माती उकरलेल्या ठिकाणी जनावरांना चरू देऊ नका.",
    "bq-firstaid-text": "जनावराला वेगळे ठेवा व मऊ बिछायत द्या. सुजलेल्या भागावर कधीही चीरा मारू नका, जंतू पसरून माती दूषित होते.",
    "ppr-prev-text": "३-४ महिने वयाच्या करडांना पीपीआर लस द्यावी जी ३ वर्षे संरक्षण देते. बाजारातून आणलेल्या नवीन शेळ्यांना १५ दिवस वेगळे ठेवा.",
    "ppr-firstaid-text": "डोळे व नाक कोमट पाण्याच्या मिठाने पुसावे. तोंडातील फोड लाल औषधाच्या पाण्याने धुवावेत. डिहायड्रेशन टाळण्यासाठी ओआरएसचे पाणी पाजावे.",
    "bloat-prev-text": "उपाशी जनावरांना ओस पडलेल्या कोवळ्या लुसर्न किंवा बरसीमच्या शेतात सोडू नका. अगोदर सुका चारा खाऊ घालावा.",
    "bloat-firstaid-text": "तोंडात लाकडाची वेसण बांधावी ज्यामुळे लाळ गळून ढेकर येईल. जनावराला चढावर हळूहळू चालवावे. २००-३०० मिली गोडेतेल (शेंगदाणा किंवा मोहरी तेल) पाजावे.",
    "anthrax-prev-text": "प्रभावित भागात दरवर्षी लस टोचावी. संशयित मृत जनावराला चुकूनही कापू नका किंवा कातडे काढू नका; जंतू हवेत पसरून जमीन ५० वर्षे दूषित होते.",
    "anthrax-firstaid-text": "रक्ताला किंवा स्रावाला हात लावू नका! मृत जनावरास ६-८ फूट खोल खड्ड्यात भरपूर चुना टाकून पुरावे.",
